15	export interface NestedEditorConfig {
16	  $getParentEditor: () => LexicalEditor;
17	  inheritEditableFromParent: boolean;
18	}
19	
20	function $defaultGetParentEditor() {
21	  const editor = $getEditor();
22	  LexicalBuilder.fromEditor(editor);
23	  return editor;
24	}
25	
26	export const NestedEditorExtension = defineExtension({
27	  build: (editor, config) =>
28	    namedSignals({inheritEditableFromParent: config.inheritEditableFromParent}),
29	  config: safeCast<NestedEditorConfig>({
30	    $getParentEditor: $defaultGetParentEditor,
31	    inheritEditableFromParent: false,
32	  }),
33	  init: (editorConfig, config, state) => {
34	    const parentEditor = config.$getParentEditor();
35	    editorConfig.parentEditor = parentEditor;
36	    editorConfig.theme = editorConfig.theme || parentEditor._config.theme;
37	  },
38	  name: '@lexical/extension/NestedEditor',
39	  register: (editor, config, state) =>
40	    effect(() => {
41	      const parentEditor = editor._parentEditor;
42	      if (parentEditor) {
43	        if (state.getOutput().inheritEditableFromParent.value) {
44	          editor.setEditable(parentEditor.isEditable());
45	          return parentEditor.registerEditableListener(
46	            editor.setEditable.bind(editor),
47	          );
48	        }
49	      }
50	    }),
51	});
