696	export function getEditorsToPropagate(
697	  editor: LexicalEditor,
698	): Array<LexicalEditor> {
699	  const editorsToPropagate: LexicalEditor[] = [];
700	  for (
701	    let currentEditor: LexicalEditor | null = editor;
702	    currentEditor !== null;
703	    // Do not propagate commands to parent editors that are
704	    // currently updating as that will trigger an early commit
705	    // and can corrupt the nodeMap by doing GC too early
706	    currentEditor = currentEditor._updating ? null : currentEditor._parentEditor
707	  ) {
708	    editorsToPropagate.push(currentEditor);
709	  }
710	  return editorsToPropagate;
711	}
