}", "newString": "/**
 * Runs the command listeners registered on a single editor (without
 * propagating to any parent editors), passing `dispatchEditor` as the editor
 * argument to each listener. The listeners run within `currentEditor`'s update
 * context, so `$getEditor()` inside a listener returns `currentEditor`.
 */
function triggerCommandListenersOnEditor<
  TCommand extends LexicalCommand<unknown>,
>(
  currentEditor: LexicalEditor,
  dispatchEditor: LexicalEditor,
  type: TCommand,
  payload: CommandPayloadType<TCommand>,
): boolean {
  const listenerInPriorityOrder = currentEditor._commands.get(type);
  if (listenerInPriorityOrder === undefined) {
    return false;
  }

  for (let i = 4; i >= 0; i--) {
    const listenersSet = listenerInPriorityOrder[i];

    if (listenersSet !== undefined) {
      const listeners = Array.from(listenersSet);
      const listenersLength = listeners.length;

      let returnVal = false;
      updateEditorSync(currentEditor, () => {
        for (let j = 0; j < listenersLength; j++) {
          if (listeners[j](payload, dispatchEditor)) {
            returnVal = true;
            return;
          }
        }
      });
      if (returnVal) {
        return true;
      }
    }
  }

  return false;
}

export function triggerCommandListeners<
  TCommand extends LexicalCommand<unknown>,
>(
  editor: LexicalEditor,
  type: TCommand,
  payload: CommandPayloadType<TCommand>,
): boolean {
  const parentEditor = editor._parentEditor;

  // Editors that opt in (e.g. via NestedEditorExtension) fully dispatch the
  // command to their own listeners first and then propagate it to the parent
  // editor's listeners. If the parent is currently updating, propagation is
  // deferred until that update finishes to avoid committing/collecting the
  // parent's pending state too early.
  if (parentEditor !== null && editor._commandsPropagateToParent) {
