      editor,
      editor,
      type,
      payload,
    );
    if (parentEditor._updating) {
      parentEditor._deferred.push(() => {
        triggerCommandListenersOnEditor(parentEditor, editor, type, payload);
      });
      return childResult;
    }
    return triggerCommandListenersOnEditor(parentEditor, editor, type, payload);
  }

